processPrePosts.script:
var logEntry = tw.local.data;

var jsonString = logEntry.substring(logEntry.indexOf('{'), logEntry.lastIndexOf('}') + 1);

var parsedData = JSON.parse(jsonString);


    tw.local.transactions = new tw.object.listOf.FCTransactions();
    tw.local.transactions = parsedData.items.map(function(item) {
        var transaction = new tw.object.FCTransactions();
        transaction.accountNo = item.accountNo;
        transaction.referenceNumber = item.referenceNumber;
        transaction.postingDate = new Date(item.postingDate); 
        transaction.valueDate = new Date(item.valueDate); 
        transaction.transactionAmount = item.transactionAmount;
        transaction.existAmount = item.existAmount;
        transaction.currency = item.currency;
        transaction.amountAllocatedForCurrencyRequest = item.amountAllocatedForCurrencyRequest;
        transaction.allocatedAmountInRequestCurrency = item.allocatedAmountInRequestCurrency;
        transaction.requestID = item.requestID;
        transaction.remove = item.remove;
        return transaction;
    });

